31	async function getUserPreferences() {
32	  const requestHeaders = await headers();
33	  const host =
34	    requestHeaders.get('x-forwarded-host') ?? requestHeaders.get('host');
35	  const protocol = requestHeaders.get('x-forwarded-proto') ?? 'http';
36	
37	  if (!host) {
38	    throw new Error('Missing host header');
39	  }
40	
41	  const cookieHeader = requestHeaders.get('cookie');
42	  const res = await fetch(`${protocol}://${host}/api/user/preferences`, {
43	    cache: 'no-store',
44	    headers: cookieHeader ? { cookie: cookieHeader } : undefined
45	  });
46	
47	  if (!res.ok) {
48	    throw new Error(
49	      `Failed to fetch user preferences: ${res.status} ${res.statusText}`
50	    );
51	  }
52	
53	  return (await res.json()) as PreferencesPayload;
54	}
